#!/usr/bin/env node
// wugweb-strategy: build.mjs
// Builds the portable files from the skill folder and the home standing-rules file,
// so agents other than Claude can load the skill. Never edit the outputs by hand.
//
//   node scripts/build.mjs           write the generated files
//   node scripts/build.mjs --check   exit 1 if any generated file is stale
//
// Sources: SKILL.md, references/*.md, docs/skills/STANDING-RULES.md, metadata.json.
// Outputs: AGENTS.md, export/wugweb-strategy.md, adapters/cursor/<name>.mdc,
// adapters/chatgpt/instructions.md, agents/openai.yaml.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const home = path.resolve(dir, '../../../docs/skills/STANDING-RULES.md');
const read = (p) => fs.readFileSync(p, 'utf8');

const skill = read(path.join(dir, 'SKILL.md'));
const front = skill.match(/^---\n([\s\S]*?)\n---\n/);
if (!front) throw new Error('SKILL.md has no frontmatter');
const name = (front[1].match(/^name:\s*(\S+)\s*$/m)?.[1] || "").replace(/^"|"$/g, "");
const descRaw = front[1].match(/^description:\s*(".*")\s*$/m)?.[1];
if (!name || !descRaw) throw new Error('SKILL.md frontmatter needs name and a double-quoted description');
const description = JSON.parse(descRaw);
const version = /version:\s*"?([\d.]+)"?/.exec(front[1])[1];
const body = skill.slice(front[0].length).trim();

const order = ['strategy','topics-and-calendar','brief-format','piece-structures','editorial-standards','content-models','proof-map','refresh-retire','campaigns-and-repurposing','performance-review','skill-map','ops'];
const refs = order.map((r) => `\n\n---\n\n<!-- references/${r}.md -->\n\n${read(path.join(dir, 'references', r + '.md')).trim()}\n`).join('');
const rules = read(home).replace(/^# .*\n/, '').trim();
export const rulesBlock = rules;

// AGENTS.md: the whole skill in one file, with the standing-rules block. Format
// is checked by scripts/test.mjs, so keep it exactly.
const agents = `# wugweb-strategy (single-file export for other tools, v${version})\n\nBuilt from the files in this folder. Rebuild whenever the skill or \`docs/skills/STANDING-RULES.md\` changes. Read the skill first, then the reference a mode names.\n\n## Owner's standing rules\n\nCopied from \`docs/skills/STANDING-RULES.md\`. That file is the source; if this block differs, that file wins.\n\n${rules}\n\n---\n\n${body}\n${refs}`;

// export/wugweb-strategy.md: the single-file paste, without the standing-rules block.
const exp = `# wugweb-strategy (single-file export, v${version})\n\nBuilt from the skill folder. Rebuild whenever the skill changes. Read the skill first, then the reference a mode names.\n\n${body}\n${refs}`;

// Cursor rule. Strategy attaches by description, not always-on; the globs cover
// its own folder and the plan docs so Cursor loads it on planning work there.
const cursor = [
  '---',
  `description: ${JSON.stringify(description)}`,
  'globs: ["**/skills/wugweb-strategy/**", "docs/skills/wugweb-strategy/**"]',
  'alwaysApply: false',
  '---',
  '',
  '<!-- Generated by scripts/build.mjs. Do not edit by hand. -->',
  '',
  body,
  '',
].join('\n');

// Custom GPT or ChatGPT project instructions.
const chatgpt = [
  '<!-- Generated by scripts/build.mjs. Do not edit by hand. -->',
  '',
  '# Instructions for a custom GPT or project',
  '',
  'Paste the block below into the instructions field. Upload `AGENTS.md` from this skill as a knowledge file.',
  '',
  '```',
  'You plan content for Wugweb, a design and digital studio, using the method in',
  'the uploaded file AGENTS.md. Read AGENTS.md before any task about what to write',
  'next, the content or social calendar, a brief, a campaign, which case study',
  'backs a page, whether a post should be refreshed or retired, or reading how',
  'posts performed. Pick one of the ten modes and name it at the top of the reply.',
  '',
  'Always:',
  '- Plan only. Hand wugweb-work a brief; never write the post, caption, headline',
  '  or body copy yourself.',
  '- Apply the fixed owner rules: British English, sentence case, no em or en',
  '  dashes, never invent a number quote or fact, result first.',
  '- Mark anything with no source "unvalidated" or "owner to set". A claim needs a',
  '  screen, a sourced number or a named fact.',
  '- Quote positioning and audiences from wugweb-brand-os as written; never',
  '  redefine them.',
  '- Show any change as current then proposed. Name no client without a recorded',
  '  permission status.',
  '- Start each reply with the mode, the sources read, and what is still "owner to',
  '  set"; end with what was not written and what needs the owner\'s go.',
  '',
  'Never:',
  '- Write or edit copy, choose screens, set layout, or publish (that is',
  '  wugweb-work).',
  '- Define positioning, values, audience or messaging (that is wugweb-brand-os).',
  '- Set keywords, titles, schema or link rules, or decide what a retired URL does',
  '  (that is wugweb-seo).',
  '- Change Sanity or Notion data, edit the schema or run a sync script (that is',
  '  wugweb-engineer). Rule on which fields a content type has; build nothing.',
  '- Write to Notion, Sanity or any account without the owner\'s go on that exact',
  '  change, with a backup first. Delete nothing.',
  '```',
  '',
].join('\n');

// Display settings for Codex and the ChatGPT desktop app. Other agents ignore it.
const openai = [
  '# Generated by scripts/build.mjs. Do not edit by hand.',
  '# Display settings for Codex and the ChatGPT desktop app. Other agents ignore this file.',
  'interface:',
  '  display_name: "wugweb-strategy"',
  '  short_description: "Plan Wugweb content and hand wugweb-work a brief"',
  '  default_prompt: "Using wugweb-strategy, plan what Wugweb should write next and show the backlog."',
  'policy:',
  '  allow_implicit_invocation: true',
  '',
].join('\n');

const outputs = {
  'AGENTS.md': agents,
  'export/wugweb-strategy.md': exp,
  [`adapters/cursor/${name}.mdc`]: cursor,
  'adapters/chatgpt/instructions.md': chatgpt,
  'agents/openai.yaml': openai,
};

const checkOnly = process.argv.includes('--check');
let stale = 0;
for (const [rel, content] of Object.entries(outputs)) {
  const full = path.join(dir, rel);
  if (checkOnly) {
    const current = fs.existsSync(full) ? read(full) : null;
    const ok = current === content;
    console.log(`${ok ? 'fresh' : 'STALE'}  ${rel}`);
    if (!ok) stale++;
  } else {
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, content);
    console.log(`wrote  ${rel}`);
  }
}
if (!checkOnly) console.log('built v' + version);
process.exit(stale ? 1 : 0);
